"""Document the design experiment and concrete stopping criteria."""
import sys,json
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
sys.path.insert(0,str(Path(__file__).resolve().parent))
from build_report_variants import Report,OUT,EX,CONFIGS
from variant_charts import METHODS,OP,OPS
from charts import report_family_groups
from corpus import load
from xml.sax.saxutils import escape
r=Report(OUT/'00_design_comparison.pdf','Сравнение вариантов визуализации','Сравнение вариантов')
r.text('Три маршрута чтения<br/>одного исследовательского корпуса','title')
r.text('Сравнение отчётов и журнал графических проб','h')
r.text('Проверены 14 графических решений для D, B/F, E и G6. Отобраны три полных отчёта: каждый содержит те же 69 методов и 43 допущенных наблюдения. Различается организация, не научные результаты.')
rows=[]
for cfg in CONFIGS:
 m=json.loads((EX/(cfg['id']+'_manifest.json')).read_text())
 rows.append([cfg['id'].split('_')[0]+' · '+cfg['title'],cfg['audience'],cfg['subtitle'],str(m['pages'])+' стр.; 4 визуальных блока'])
r.table(['Вариант','Когда читать','Категоризация D','Объём'],rows,[66,91,67,43])
r.text('<b>Рекомендуемый основной вариант: 01.</b> Матрица «действие × входы» отвечает на вопрос о требованиях без категории «разные требования»; численные протоколы имеют общие строки и независимые оси. 02 удобнее для выбора при ограничениях на данные, 03 — для компактного обзора тематических семейств.')
r.text('Основные визуальные блоки: D, совмещённый B/F, E и G6. В 02 и 03 последний блок — таблица. A/C не превращены в пустые или условные графики: отсутствующие полные стоимости не создают ось времени. Полные перечисления методов идут сразу после D, исключения — в конце каждого отчёта.')
r.page();r.heading('Почему меняются категории')
r.text('Тематическое семейство описывает исследовательскую традицию; операционная группа — действие при оценке нового кандидата. Матрица переходов ниже является точным пересчётом 69 записей, а не субъективной близостью методов.')
rows=[]
for g in report_family_groups(METHODS):rows.append([g['id']+' · '+g['title']]+[str(sum(OP[m['id']]==op['id'] for m in g['methods'])) for op in OPS]+[str(len(g['methods']))])
r.table(['Исходное семейство']+[o['id'] for o in OPS]+['Всего'],rows,[113]+[22]*7)
for op in OPS:r.text('<b>'+op['id']+' · '+escape(op['short'])+'</b>. '+escape(op['definition']),'small')
r.text('Граница O2/O3: поиск или настройка коэффициента proxy-формулы не становится отдельным регрессором автоматически. M26 остаётся в O2; M31 с MABN — O3. Гибрид, которому нужна частичная кривая именно нового кандидата, относится к O4. Это правило применено до изображения численных результатов.','small')
r.page();r.heading('3D-проба · Не выбрана для основного текста')
r.text('Третья ось кодирует наличие хотя бы одного допущенного наблюдения для ID метода. Это состояние корпуса, не вероятность применимости. Подпись около точки — число методов; размер лишь помогает увидеть заполненность.','small');r.figure('D_3d',128)
r.text('Проверенный ракурс показывает 16 занятых ячеек, но перспективная глубина и коды O1–O6 требуют дополнительного чтения. Категории не имеют метрического расстояния. Добавлять ещё одну ось стоимости нельзя: полных стоимостей нет. Для статического PDF этот вариант проигрывает плоской карте.','small')
r.page();r.heading('Те же данные · Двумерные срезы')
r.figure('D_evidence_facets',130)
r.text('36 явно подписанных ячеек читаются проще, чем перспективная глубина. Но это удвоение основной карты ради дополнительного вопроса о покрытии корпуса. В отчётах оставлены 18 ячеек D и сводка 24 ID методов с допущенными числами; детальные срезы сохранены в экспорте для аудита.')
r.text('«Есть числа» означает наличие хотя бы одного допущенного варианта с тем же method ID; не все адаптации этого метода проверены. Для конкретного применения следует сверяться с вариантом и источником.','small')
r.page();r.heading('Пример неудачного компромисса · Две метрики на двух осях')
r.text('G6: scatter выглядит компактно, но близкие LM-варианты и их подписи сливаются. Добавление zoom решило бы наложение ценой ещё одной панели, не отвечающей на новый исследовательский вопрос.','small');r.figure('G6_scatter',120)
r.text('Поэтому в варианте 01 используются две независимые колонки точек, а в 02/03 — точная таблица. Значения 0.745 и 0.746 видны без увеличения; Spearman и Kendall не усредняются. Это диагностическая страница отвергнутой пробы, не научный график итогового отчёта.','small')
r.page();r.heading('Решения по всем 14 пробам')
rows=[]
review=load('visualization_design_review')
for item in review['decisions']:
 rows.append([item['id'],{'selected':'Выбран','diagnostic_only':'Только аудит','rejected':'Отклонён'}[item['decision']],item['reason']])
r.table(['Проба','Решение','Основание'],rows,[39,28,200])
r.page();r.heading('Проверка завершения перебора')
for i,criterion in enumerate(review['stop_conditions'],1):r.text(str(i)+'. '+escape(criterion))
r.text('Численная сохранность проверяется тестами tests/test_report_variants.py: покрытие ID, разбиение методов, отсутствие повторов наблюдений, исходные значения и SD, вариант-зависимые входы и исключение отклонённых графиков. Визуальная проверка выполняется по отрендеренным страницам, отдельно от этих тестов.','small')
r.text('Критерий остановки — три читаемых решения для разных задач, а не максимальное число вариантов или заявление о глобально оптимальной таксономии. Дальнейшее дробление возможно при новом вопросе, но в текущем отчёте оно добавило бы категории без новой необходимой развилки выбора.','small')
r.text('Воспроизводимость: uv run python scripts/build_visualization_experiments.py; uv run python scripts/build_report_variants.py; uv run python scripts/build_design_comparison.py. Графики, исходные строки и манифесты: exports/variants/. Определения категорий: data/visualization_taxonomies.json.','small')
r.build();print(r.path)
